sys_script_include.script:
var TaskUtils = Class.create();
TaskUtils.prototype = {
    initialize: function() {},

    getTasks: function(userID, state) {
        var tasks = [];

		var gr = new GlideRecord('x_snc_task_mger_task');
        gr.addQuery('user', userID);
        gr.addQuery('state', state);
        gr.query();
        while (gr.next()) {
            tasks.push({
                sys_id: gr.getValue('sys_id'),
                short_description: gr.getValue('short_description')
            });
        }

        return tasks;
    },

    type: 'TaskUtils'
};
